    10	export async function headSha(cwd: string): Promise<string> {
    11	  const r = await runCommand("git", ["rev-parse", "HEAD"], { cwd });
    12	  if (!r.ok) throw new Error(`cannot read HEAD: ${r.error} (${r.command})`);
    13	  return r.stdout.trim();
    14	}
    15	
    16	/**
    17	 * A contract proposed against an already-modified tree adjudicates nothing,
    18	 * so propose_change fails closed on a dirty tree. Deliberate.
    19	 */
    20	export async function dirtyFiles(cwd: string): Promise<string[]> {
    21	  const r = await runCommand("git", ["status", "--porcelain"], { cwd });
    22	  if (!r.ok) throw new Error(`cannot read git status: ${r.error} (${r.command})`);
    23	  return r.stdout
    24	    .split("\n")
    25	    .map((l) => l.slice(3).trim())
    26	    .filter(Boolean);
    27	}
    28	
    29	/** Files touched since the contract was written: committed and uncommitted. */
    30	export async function changedSince(
    31	  cwd: string,
    32	  baseSha: string,
    33	): Promise<{ files: string[]; provenance: Provenance }> {
    34	  const tracked = await runCommand("git", ["diff", "--name-only", baseSha], { cwd });
    35	  if (!tracked.ok) {
    36	    throw new Error(`cannot diff against ${baseSha}: ${tracked.error} (${tracked.command})`);
    37	  }
    38	  const untracked = await runCommand(
    39	    "git",
    40	    ["ls-files", "--others", "--exclude-standard"],
    41	    { cwd },
    42	  );
    43	  const files = new Set<string>();
    44	  for (const line of tracked.stdout.split("\n")) if (line.trim()) files.add(line.trim());
    45	  if (untracked.ok) {
    46	    for (const line of untracked.stdout.split("\n")) if (line.trim()) files.add(line.trim());
    47	  }
    48	  return {
    49	    files: [...files],
    50	    provenance: {
    51	      source: "git",
    52	      command: tracked.command,
    53	      confidence: "deterministic",
    54	    },
