    14	export type CommandResult = {
    15	  command: string;
    16	  stdout: string;
    17	  stderr: string;
    18	  ok: boolean;
    19	  /** Present when the command failed; the caller decides degrade vs. throw. */
    20	  error?: string;
    21	};
    22	
    23	export function renderCommand(bin: string, args: string[]): string {
    24	  return [bin, ...args.map((a) => (a.includes(" ") ? JSON.stringify(a) : a))].join(" ");
    25	}
    26	
    27	export async function runCommand(
    28	  bin: string,
    29	  args: string[],
    30	  opts: { cwd: string; maxBuffer?: number; timeoutMs?: number } = { cwd: process.cwd() },
    31	): Promise<CommandResult> {
    32	  const command = renderCommand(bin, args);
    33	  try {
    34	    const { stdout, stderr } = await run(bin, args, {
    35	      cwd: opts.cwd,
    36	      maxBuffer: opts.maxBuffer ?? 64 * 1024 * 1024,
    37	      timeout: opts.timeoutMs ?? 120_000,
    38	      windowsHide: true,
    39	    });
    40	    return { command, stdout, stderr, ok: true };
    41	  } catch (err) {
    42	    const e = err as { stdout?: string; stderr?: string; message?: string };
    43	    return {
    44	      command,
    45	      stdout: e.stdout ?? "",
    46	      stderr: e.stderr ?? "",
    47	      ok: false,
    48	      error: (e.stderr || e.message || "command failed").trim(),
    49	    };
    50	  }
    51	}
    52	
    53	/** Parse stdout as JSON, tolerating a leading banner line some CLIs emit. */
    54	export function parseJson<T>(result: CommandResult): T | undefined {
    55	  const text = result.stdout.trim();
    56	  if (!text) return undefined;
    57	  try {
    58	    return JSON.parse(text) as T;
    59	  } catch {
    60	    const start = text.search(/[[{]/);
    61	    if (start < 0) return undefined;
    62	    try {
    63	      return JSON.parse(text.slice(start)) as T;
    64	    } catch {
    65	      return undefined;
    66	    }
    67	  }
    68	}

