     1	#!/usr/bin/env node
     2	/**
     3	 * CLI entrypoint over the same core as the MCP server.
     4	 *
     5	 * Two reasons this exists, both deliberate:
     6	 *  1. CI. A pull-request check needs a verdict and an exit code, not a protocol.
     7	 *  2. Fallback. If an MCP client will not connect during a demo, the product
     8	 *     still runs. The logic is the product; MCP is the delivery.
     9	 *
    10	 * Exit codes: 0 = PASS, 1 = WARN, 2 = FAIL, 3 = error.
    11	 */
    12	import { propose, verify } from "./core.js";
    13	import { formatContract, formatVerdict } from "./format.js";
    14	
    15	function usage(): string {
    16	  return [
    17	    "entire-guard - hold a coding agent to the blast radius it was given",
    18	    "",
    19	    "  entire-guard propose <symbol|file:line> [--depth 1|2] [--repo PATH] [--allow-dirty]",
    20	    "  entire-guard verify  [contract_id] [--repo PATH] [--json]",
    21	    "",
    22	    "Exit codes: 0 PASS, 1 WARN, 2 FAIL, 3 error.",
    23	  ].join("\n");
    24	}
    25	
    26	function flagValue(argv: string[], name: string): string | undefined {
    27	  const i = argv.indexOf(name);
    28	  return i >= 0 ? argv[i + 1] : undefined;
    29	}
    30	
    31	async function main(): Promise<number> {
    32	  const argv = process.argv.slice(2);
    33	  const command = argv[0];
    34	  const repo = flagValue(argv, "--repo");
    35	
    36	  if (command === "propose") {
    37	    const symbol = argv[1];
    38	    if (!symbol || symbol.startsWith("--")) {
    39	      process.stderr.write("propose needs a symbol or file:line selector\n\n" + usage() + "\n");
    40	      return 3;
    41	    }
    42	    const depthRaw = flagValue(argv, "--depth");
    43	    const depth = depthRaw === "1" ? 1 : depthRaw === "2" ? 2 : undefined;
    44	    const { contract, file } = await propose({
    45	      symbol,
    46	      repo,
    47	      depth,
    48	      allow_dirty: argv.includes("--allow-dirty"),
    49	    });
    50	    process.stdout.write(formatContract(contract, file) + "\n");
    51	    return 0;
    52	  }
    53	
    54	  if (command === "verify") {
    55	    const maybeId = argv[1] && !argv[1].startsWith("--") ? argv[1] : undefined;
    56	    const verdict = await verify({ contract_id: maybeId, repo });
    57	    if (argv.includes("--json")) {
    58	      process.stdout.write(JSON.stringify(verdict, null, 2) + "\n");
    59	    } else {
    60	      process.stdout.write(formatVerdict(verdict) + "\n");
    61	    }
    62	    return verdict.status === "FAIL" ? 2 : verdict.status === "WARN" ? 1 : 0;
    63	  }
    64	
    65	  process.stdout.write(usage() + "\n");
    66	  return command ? 3 : 0;
    67	}
    68	
    69	main()
    70	  .then((code) => process.exit(code))
    71	  .catch((err: unknown) => {
    72	    process.stderr.write((err instanceof Error ? err.message : String(err)) + "\n");
    73	    process.exit(3);
    74	  });

