     1	/**
     2	 * The adjudicator.
     3	 *
     4	 * This is a pure function: (contract, actualChanges, policy) -> Verdict.
     5	 * It performs no I/O, shells out to nothing, and reads no clock. That is a
     6	 * deliberate testability decision -- it is unit-testable against fixtures with
     7	 * zero CLI dependency, and it is the same code path a CI entrypoint would use
     8	 * without an MCP server anywhere in sight.
     9	 *
    10	 * The logic is set arithmetic over file paths. Same inputs -> same verdict,
    11	 * byte for byte. No model in the critical path.
    12	 */
    13	import type {
    14	  ActualChanges,
    15	  ChangeContract,
    16	  Policy,
    17	  Verdict,
    18	} from "../types.js";
    19	
    20	/**
    21	 * Normalise a path for comparison: forward slashes, no leading "./".
    22	 * Windows and git disagree about separators; the adjudicator must not care.
    23	 */
    24	export function normalisePath(p: string): string {
    25	  return p.split("\\").join("/").replace(/^\.\//, "").trim();
    26	}
    27	
    28	function isAlwaysAllowed(path: string, policy: Policy): boolean {
    29	  return policy.always_allowed.some(
    30	    (prefix) => path === prefix || path.startsWith(normalisePath(prefix)),
    31	  );
    32	}
    33	
    34	/** Go/TS/Python test-file heuristics, used only when policy.exclude_tests is on. */
    35	function looksLikeTest(path: string): boolean {
    36	  return /(^|\/)(test|tests|__tests__)\//.test(path) || /(_test\.|\.test\.|\.spec\.)/.test(path);
    37	}
    38	
    39	export function adjudicate(
    40	  contract: ChangeContract,
    41	  actual: ActualChanges,
    42	  policy: Policy = contract.policy,
    43	): Verdict {
    44	  const changed = new Set(actual.changed_files.map(normalisePath));
    45	
    46	  // The legitimate blast radius: everything the graph proved reachable, plus
    47	  // the obliged callers, plus the target file itself.
    48	  const allowed = new Set<string>();
    49	  for (const f of contract.allowed_files) allowed.add(normalisePath(f.path));
    50	  for (const m of contract.must_update) allowed.add(normalisePath(m.path));
    51	  if (contract.target.file) allowed.add(normalisePath(contract.target.file));
    52	
    53	  const out_of_bounds: Verdict["out_of_bounds"] = [];
    54	  const in_bounds: string[] = [];
    55	
    56	  for (const path of changed) {
    57	    if (allowed.has(path) || isAlwaysAllowed(path, policy)) {
    58	      in_bounds.push(path);
    59	      continue;
    60	    }
    61	    if (policy.exclude_tests && looksLikeTest(path)) {
    62	      in_bounds.push(path);
    63	      continue;
    64	    }
    65	    out_of_bounds.push({
    66	      path,
    67	      note: "edited, but not in the blast radius proved by graph impact for " + contract.target.symbol,
    68	      provenance: {
    69	        source: "git",
    70	        command: `git diff --name-only ${contract.base_sha}`,
    71	        confidence: "deterministic",
    72	      },
    73	    });
    74	  }
    75	
    76	  // The headline finding: a direct caller that was obliged to change and did not.
    77	  // A diff cannot show this, because the evidence is an absence.
    78	  const forgotten: Verdict["forgotten"] = [];
    79	  for (const m of contract.must_update) {
    80	    const path = normalisePath(m.path);
    81	    if (changed.has(path)) continue;
    82	    if (policy.exclude_tests && looksLikeTest(path)) continue;
    83	    forgotten.push({
    84	      path,
    85	      symbol: m.symbol,
    86	      relation: m.relation,
    87	      provenance: m.provenance,
    88	    });
    89	  }
    90	
    91	  // Heuristic: historically co-changing files left untouched. This is how
    92	  // cross-module drift shows up (separate modules, so no compiler links them).
    93	  // FILE_CHANGES_WITH is a heuristic relation -- WARN only, never FAIL.
    94	  const drift_candidates: Verdict["drift_candidates"] = [];
    95	  if (changed.size > 0) {
    96	    for (const d of contract.drift_candidates) {
    97	      const path = normalisePath(d.path);
    98	      if (changed.has(path)) continue;
    99	      drift_candidates.push({ path, detail: d.detail, provenance: d.provenance });
   100	    }
   101	  }
   102	
   103	  // A known unresolved risk in territory this change touched.
   104	  const traps_hit: Verdict["traps_hit"] = [];
   105	  for (const trap of contract.known_traps) {
   106	    for (const f of trap.files) {
   107	      const path = normalisePath(f);
   108	      if (!changed.has(path)) continue;
   109	      traps_hit.push({
   110	        text: trap.text,
   111	        checkpoint_id: trap.checkpoint_id,
   112	        path,
   113	        provenance: trap.provenance,
   114	      });
   115	      break;
   116	    }
   117	  }
   118	
   119	  const degraded = [...contract.degraded, ...actual.degraded];
   120	
   121	  const failing =
   122	    (policy.fail_on.includes("out_of_bounds") && out_of_bounds.length > 0) ||
   123	    (policy.fail_on.includes("forgotten") && forgotten.length > 0) ||
   124	    (policy.fail_on_degraded && degraded.length > 0);
   125	
   126	  const warning =
   127	    traps_hit.length > 0 ||
   128	    drift_candidates.length > 0 ||
   129	    out_of_bounds.length > 0 ||
   130	    forgotten.length > 0 ||
   131	    degraded.length > 0;
   132	
   133	  const status: Verdict["status"] = failing ? "FAIL" : warning ? "WARN" : "PASS";
   134	
   135	  return {
   136	    status,
   137	    out_of_bounds,
   138	    forgotten,
   139	    drift_candidates,
   140	    traps_hit,
   141	    in_bounds: in_bounds.sort(),
   142	    semantic_changes: actual.semantic_changes,
   143	    degraded,
   144	    contract_id: contract.id,
   145	    base_sha: contract.base_sha,
   146	    head_sha: actual.head_sha,
   147	  };
   148	}

