/* ------------------------------------------------------------------------- *
 * Agent session transcripts
 *
 * Added for the Noon Curveball. The agent's own transcript is a second record
 * of what changed -- and unlike a diff, it arrives in a format that can change
 * underneath us. These types are what every format normalises into, so that
 * exactly one adjudicator serves all of them.
 * ------------------------------------------------------------------------- */

/**
 * A transcript format we can read.
 *
 * "entire-protocol" -- this repository's external-agent protocol: numeric
 *   `EventJSON.type`, `HookInputJSON.hook_type`, `AgentSessionJSON` file lists.
 * "acme-events" -- the format introduced by the Curveball: a string-tagged
 *   event envelope with per-edit `file_changed` records.
 */
export type SessionFormat = "entire-protocol" | "acme-events";

/**
 * One file the agent says it changed.
 *
 * This is a claim, not an observation. `kind` is the final state reported for
 * the path; `events` counts how many times the transcript mentioned it, which
 * is how a stream format and a batch format stay distinguishable after
 * normalisation.
 */
export type ClaimedChange = {
  path: string;
  kind: "modified" | "created" | "deleted";
  summary?: string;
  /** 1-based line in the transcript where the path was first reported. */
  line: number;
  events: number;
};

/** A checkpoint the transcript says was created, with any unresolved questions. */
export type SessionCheckpoint = {
  checkpoint_id: string;
  git_commit?: string;
  intent?: string;
  summary?: string;
  open_questions: string[];
  /** 1-based line in the transcript. */
  line: number;
};

/**
 * An event kind this integration does not understand.
 *
 * Recorded rather than thrown: a format is allowed to grow events we have never
 * seen, and an unknown event is not a reason to discard a session. It *is* a
 * reason to say so, because an unread event may have carried a file change.
 */
export type UnknownEvent = { name: string; count: number; first_line: number };

/** The normalised form every transcript format is read into. */
export type AgentSession = {
  format: SessionFormat;
  /** Where this came from, for provenance. */
  source: string;
  session_id?: string;
  agent?: string;
  repo?: string;
  claimed_changes: ClaimedChange[];
  lifecycle: { started: boolean; ended: boolean; status?: string };
  checkpoints: SessionCheckpoint[];
  unknown_events: UnknownEvent[];
  records_parsed: number;
  /**
   * True only when the transcript ended cleanly *and* every line parsed.
   * A false value makes PASS unreachable -- see EvidenceBasis.
   */
  complete: boolean;
  degraded: string[];
  provenance: Provenance;
};

/**
 * The result of reading a transcript.
 *
 * `session` is absent when the format could not be established. That is a
 * refusal, not an empty session: guessing a format would silently produce zero
 * claims, which is exactly the "confident but wrong" failure this codebase
 * treats as the worst outcome.
 */
export type SessionEvidence = {
  session?: AgentSession;
  degraded: string[];
  provenance: Provenance;
};

/**
 * Transcript format detection.
 *
 * The rule this file exists to enforce: **refuse rather than guess.**
 *
 * Guessing a format is worse than failing to read the transcript at all. A
 * wrong guess yields zero parsed file changes and a confident-looking empty
 * session -- the same "compiled, ran, reported success, did nothing" failure
 * class this product was built to catch. So an absent or contradictory
 * discriminator returns no format and an explanation.
 */
import type { JsonlRecord } from "../exec.js";
import type { SessionFormat } from "../../types.js";

export type Detection = { format?: SessionFormat; reason: string };

/** How many records to sniff. A transcript's shape is settled by its first few lines. */
const SNIFF_LIMIT = 50;

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Does this record look like the Curveball's event envelope?
 * Discriminator: a string `event`.
 */
function looksAcme(o: Record<string, unknown>): boolean {
  return typeof o["event"] === "string";
}

/**
 * Does this record look like one of the external-agent protocol structs?
 * Three discriminators, because the protocol has three record shapes:
 *   EventJSON        -> numeric `type`
 *   HookInputJSON    -> string `hook_type`
 *   AgentSessionJSON -> one of the file-list arrays, or `agent_name`
 */
function looksEntireProtocol(o: Record<string, unknown>): boolean {
  if (typeof o["type"] === "number") return true;
  if (typeof o["hook_type"] === "string") return true;
  if (typeof o["agent_name"] === "string") return true;
  return (
    Array.isArray(o["modified_files"]) ||
    Array.isArray(o["new_files"]) ||
    Array.isArray(o["deleted_files"])
  );
}

export function detectFormat(records: JsonlRecord[]): Detection {
  if (records.length === 0) {
    return {
      reason:
        "could not determine the transcript format: no readable JSONL records (the file is empty, or every line failed to parse)",
    };
  }

  let acme = 0;
  let protocol = 0;

  for (const record of records.slice(0, SNIFF_LIMIT)) {
    if (!isObject(record.value)) continue;
    if (looksAcme(record.value)) acme += 1;
    if (looksEntireProtocol(record.value)) protocol += 1;
  }

  if (acme > 0 && protocol > 0) {
    return {
      reason:
        `transcript format is ambiguous: ${acme} record(s) carry a string "event" (new format) and ` +
        `${protocol} carry a numeric "type" / "hook_type" / file-list field (original format). ` +
        "Refusing to guess -- split the transcript, or supply the one the agent actually wrote.",
    };
  }

  if (acme > 0) return { format: "acme-events", reason: `${acme} string-tagged event record(s)` };
  if (protocol > 0) {
    return { format: "entire-protocol", reason: `${protocol} protocol record(s)` };
  }

  return {
    reason:
      `could not determine the transcript format: ${records.length} record(s) parsed as JSON but none ` +
      'carried a recognised discriminator (a string "event", or a numeric "type" / "hook_type" / file-list field)',
  };
}

/**
 * The shared normalisation layer.
 *
 * The Track 3 card forbids duplicating the implementation per format. This file
 * is how that rule is kept: claim de-duplication, unknown-event counting and
 * lifecycle accumulation live here exactly once, and a format reader is reduced
 * to deciding *which* accumulator call each record maps to.
 *
 * The two formats report changes in structurally different ways -- one hands
 * over a set of files at the end, the other streams an event per edit. The
 * accumulator absorbs that difference, which is why a shared schema would not
 * have worked but a shared accumulator does.
 */
import type { ClaimedChange, SessionCheckpoint, UnknownEvent } from "../../types.js";

export type Accumulator = {
  session_id?: string;
  agent?: string;
  repo?: string;
  /** Keyed by normalised path, so a stream format and a batch format converge. */
  claims: Map<string, ClaimedChange>;
  lifecycle: { started: boolean; ended: boolean; status?: string };
  checkpoints: SessionCheckpoint[];
  unknown: Map<string, UnknownEvent>;
};

export function newAccumulator(): Accumulator {
  return {
    claims: new Map(),
    lifecycle: { started: false, ended: false },
    checkpoints: [],
    unknown: new Map(),
  };
}

/** Forward slashes, no leading "./" -- the same rule the adjudicator applies. */
export function normaliseClaimPath(p: string): string {
  return p.split("\\").join("/").replace(/^\.\//, "").trim();
}

/**
 * Record one claimed change.
 *
 * De-duplicated by path. `kind` is the *last* reported state, because that is
 * the one that can be reconciled against a diff: a file created and then
 * modified is, on disk, created. `line` stays the first sighting so a reader
 * can find where the claim entered the transcript, and `events` counts the
 * mentions, which is the only place the stream-versus-batch distinction
 * survives normalisation.
 */
export function addClaim(
  acc: Accumulator,
  rawPath: string,
  kind: ClaimedChange["kind"],
  line: number,
  summary?: string,
): void {
  const path = normaliseClaimPath(rawPath);
  if (!path) return;

  const existing = acc.claims.get(path);
  if (!existing) {
    acc.claims.set(path, { path, kind, line, events: 1, ...(summary ? { summary } : {}) });
    return;
  }

  existing.kind = kind;
  existing.events += 1;
  if (!existing.summary && summary) existing.summary = summary;
}

/**
 * Record an event kind we do not understand.
 *
 * Counted, never thrown, and never a reason to discard the session. It is still
 * disclosed, because an unread event may have carried a file change -- which is
 * a gap in what we know, not a licence to assume nothing happened.
 */
export function noteUnknown(acc: Accumulator, name: string, line: number): void {
  const existing = acc.unknown.get(name);
  if (existing) {
    existing.count += 1;
    return;
  }
  acc.unknown.set(name, { name, count: 1, first_line: line });
}

/** First non-empty value wins, so the earliest record establishes identity. */
export function noteIdentity(
  acc: Accumulator,
  field: "session_id" | "agent" | "repo",
  value: unknown,
): void {
  if (typeof value !== "string" || value.trim() === "") return;
  if (acc[field]) return;
  acc[field] = value.trim();
}

export function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

export function asString(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() !== "" ? v.trim() : undefined;
}

export function asStringArray(v: unknown): string[] {
  if (!Array.isArray(v)) return [];
  return v.filter((x): x is string => typeof x === "string" && x.trim() !== "").map((x) => x.trim());
}

/**
 * Reader for the NEW format introduced by the Noon Curveball.
 *
 * A string-tagged event envelope, one JSON object per line, with file changes
 * arriving as a **stream**: one `file_changed` event per edit, so a file edited
 * twice appears twice.
 *
 * This file is one of only two places in the codebase that knows a transcript
 * format exists. Everything downstream -- reconciliation, adjudication,
 * formatting, both transports -- works on the normalised session.
 */
import type { JsonlRecord } from "../../exec.js";
import {
  addClaim,
  asString,
  asStringArray,
  isObject,
  newAccumulator,
  noteIdentity,
  noteUnknown,
  type Accumulator,
} from "../normalize.js";
import type { ClaimedChange } from "../../../types.js";

/**
 * Events we understand and deliberately take no action on.
 *
 * Listed explicitly rather than ignored by default, so that a genuinely new
 * event kind shows up in `unknown_events` instead of being silently swallowed.
 */
const KNOWN_INERT = new Set([
  "user_prompt",
  "agent_response",
  "tool_call",
  "tool_result",
  "file_read",
  "usage",
]);

/** `change` values the format uses, mapped onto our three kinds. */
function claimKind(change: unknown): ClaimedChange["kind"] {
  const c = asString(change)?.toLowerCase();
  if (c === "created" || c === "added" || c === "new") return "created";
  if (c === "deleted" || c === "removed") return "deleted";
  return "modified";
}

export function readAcmeEvents(records: JsonlRecord[]): Accumulator {
  const acc = newAccumulator();

  for (const record of records) {
    if (!isObject(record.value)) {
      noteUnknown(acc, "non-object record", record.line);
      continue;
    }
    const o = record.value;
    const event = asString(o["event"]);
    if (!event) {
      noteUnknown(acc, "record without an event name", record.line);
      continue;
    }

    noteIdentity(acc, "session_id", o["session_id"]);

    switch (event) {
      case "session_started": {
        acc.lifecycle.started = true;
        const agent = o["agent"];
        if (isObject(agent)) {
          const name = asString(agent["name"]);
          const version = asString(agent["version"]);
          noteIdentity(acc, "agent", name && version ? `${name} ${version}` : name);
        }
        noteIdentity(acc, "repo", o["repository"]);
        break;
      }

      case "session_ended": {
        acc.lifecycle.ended = true;
        acc.lifecycle.status = asString(o["status"]);
        break;
      }

      case "file_changed": {
        const path = asString(o["path"]) ?? asString(o["file_path"]);
        if (!path) {
          noteUnknown(acc, "file_changed without a path", record.line);
          break;
        }
        addClaim(acc, path, claimKind(o["change"]), record.line, asString(o["summary"]));
        break;
      }

      case "checkpoint_created": {
        const id = asString(o["checkpoint_id"]);
        if (!id) {
          noteUnknown(acc, "checkpoint_created without a checkpoint_id", record.line);
          break;
        }
        acc.checkpoints.push({
          checkpoint_id: id,
          line: record.line,
          open_questions: asStringArray(o["open_questions"]),
          ...(asString(o["git_commit"]) ? { git_commit: asString(o["git_commit"])! } : {}),
          ...(asString(o["intent"]) ? { intent: asString(o["intent"])! } : {}),
          ...(asString(o["summary"]) ? { summary: asString(o["summary"])! } : {}),
        });
        break;
      }

      default: {
        if (!KNOWN_INERT.has(event)) noteUnknown(acc, event, record.line);
        break;
      }
    }
  }

  return acc;
}

/**
 * Reader for the ORIGINAL format: this repository's external-agent protocol.
 *
 * Three record shapes, taken from each agent's `internal/protocol/types.go`:
 *
 *   EventJSON        numeric `type` -- lifecycle. Observed values in this repo:
 *                    1 agent-spawn, 2 user-prompt-submit, 3 stop. `goose` also
 *                    emits 5, whose meaning is not documented here, so it is
 *                    treated as unknown rather than assumed.
 *   HookInputJSON    string `hook_type`, plus `tool_name` and `tool_input`.
 *   AgentSessionJSON `modified_files` / `new_files` / `deleted_files` -- the
 *                    authoritative **batch summary** of what the session changed.
 *
 * One deliberate restraint, and it matters: `EventJSON` carries `tool_input` but
 * **no `tool_name`**. A `file_path` on an EventJSON therefore cannot be shown to
 * be an edit rather than a read, so it is *not* counted as a claimed change.
 * Only `HookInputJSON`, which does carry `tool_name`, can contribute a
 * tool-derived claim. Over-counting claims would be the wrong kind of error: it
 * would let a path the agent merely read stand as a path the agent changed.
 */
import type { JsonlRecord } from "../../exec.js";
import {
  addClaim,
  asString,
  asStringArray,
  isObject,
  newAccumulator,
  noteIdentity,
  noteUnknown,
  type Accumulator,
} from "../normalize.js";

/** Integer lifecycle values observed in this repository's agents. */
const EVENT_SESSION_START = 1;
const EVENT_USER_PROMPT = 2;
const EVENT_STOP = 3;

/** Hook names declared by the agents in this repository. */
const KNOWN_HOOKS = new Set([
  "agent-spawn",
  "user-prompt-submit",
  "pre-tool-use",
  "post-tool-use",
  "stop",
  "session_start",
]);

/**
 * Does this tool name denote a write?
 *
 * Deliberately a name-shape heuristic, because every agent names its editor
 * differently (`fsWrite`, `str_replace_editor`, `edit_file`, `Write`). The
 * consequence of it missing a writer is that a claim goes uncounted -- which,
 * under the additive-only rule, can never make a verdict more permissive. The
 * consequence of it over-matching would be a false claim, so it errs narrow.
 */
function isWriteTool(name: string): boolean {
  return /(write|edit|create|append|replace|insert|patch|delete|remove|mkdir|rename|move)/i.test(
    name,
  );
}

function toolPath(input: unknown): string | undefined {
  if (!isObject(input)) return undefined;
  return (
    asString(input["path"]) ??
    asString(input["file_path"]) ??
    asString(input["filePath"]) ??
    asString(input["target_file"])
  );
}

export function readEntireProtocol(records: JsonlRecord[]): Accumulator {
  const acc = newAccumulator();

  for (const record of records) {
    if (!isObject(record.value)) {
      noteUnknown(acc, "non-object record", record.line);
      continue;
    }
    const o = record.value;
    noteIdentity(acc, "session_id", o["session_id"]);

    // --- EventJSON: numeric lifecycle type -------------------------------
    if (typeof o["type"] === "number") {
      const t = o["type"];
      if (t === EVENT_SESSION_START) acc.lifecycle.started = true;
      else if (t === EVENT_STOP) acc.lifecycle.ended = true;
      else if (t !== EVENT_USER_PROMPT) noteUnknown(acc, `type:${t}`, record.line);
      continue;
    }

    // --- HookInputJSON: named hook, possibly a tool call -----------------
    const hook = asString(o["hook_type"]);
    if (hook) {
      if (!KNOWN_HOOKS.has(hook)) {
        noteUnknown(acc, `hook:${hook}`, record.line);
        continue;
      }
      if (hook === "agent-spawn" || hook === "session_start") acc.lifecycle.started = true;
      if (hook === "stop") acc.lifecycle.ended = true;
      if (hook === "post-tool-use") {
        const tool = asString(o["tool_name"]);
        const path = toolPath(o["tool_input"]);
        if (tool && path && isWriteTool(tool)) {
          addClaim(acc, path, "modified", record.line, `${tool} reported writing this path`);
        }
      }
      continue;
    }

    // --- AgentSessionJSON: the authoritative batch summary ---------------
    const isSessionSummary =
      typeof o["agent_name"] === "string" ||
      Array.isArray(o["modified_files"]) ||
      Array.isArray(o["new_files"]) ||
      Array.isArray(o["deleted_files"]);

    if (isSessionSummary) {
      noteIdentity(acc, "agent", o["agent_name"]);
      noteIdentity(acc, "repo", o["repo_path"]);
      for (const p of asStringArray(o["modified_files"])) {
        addClaim(acc, p, "modified", record.line, "AgentSessionJSON.modified_files");
      }
      for (const p of asStringArray(o["new_files"])) {
        addClaim(acc, p, "created", record.line, "AgentSessionJSON.new_files");
      }
      for (const p of asStringArray(o["deleted_files"])) {
        addClaim(acc, p, "deleted", record.line, "AgentSessionJSON.deleted_files");
      }
      continue;
    }

    noteUnknown(acc, "unrecognised protocol record", record.line);
  }

  return acc;
}

/**
 * Session transcript evidence -- the entry point.
 *
 * Added for the Noon Curveball. Before it, entire-guard learned what an agent
 * changed from exactly one source with no format at all: `git diff --name-only`.
 * That source is still here and still deterministic; this one sits *beside* it
 * and is explicitly weaker -- a transcript is the agent's own account, so every
 * claim it yields carries `confidence: "claimed"`.
 *
 * The registry below is the extension point. A third format is one reader file
 * and one row.
 */
import { readFile } from "node:fs/promises";
import { parseJsonl } from "../exec.js";
import { detectFormat } from "./detect.js";
import { readAcmeEvents } from "./readers/acme-events.js";
import { readEntireProtocol } from "./readers/entire-protocol.js";
import type { Accumulator } from "./normalize.js";
import type { JsonlRecord } from "../exec.js";
import type { AgentSession, Provenance, SessionEvidence, SessionFormat } from "../../types.js";

/** The only place that maps a detected format to the code that reads it. */
const READERS: Record<SessionFormat, (records: JsonlRecord[]) => Accumulator> = {
  "acme-events": readAcmeEvents,
  "entire-protocol": readEntireProtocol,
};

function provenanceFor(source: string): Provenance {
  return {
    source: "transcript",
    command: `read agent session transcript ${source}`,
    confidence: "claimed",
  };
}

/**
 * Read a transcript into the normalised session shape.
 *
 * Pure: text in, evidence out. No filesystem, no clock -- the same testability
 * decision the adjudicator rests on.
 *
 * Never throws. An unreadable line, an unknown event and an unrecognisable
 * format are three different outcomes and all three are reported rather than
 * raised, because the card requires an incomplete transcript to yield a partial
 * result rather than a discarded session.
 */
export function parseSession(text: string, source: string): SessionEvidence {
  const provenance = provenanceFor(source);
  const parsed = parseJsonl(text);
  const detection = detectFormat(parsed.records);

  if (!detection.format) {
    // A refusal, not an empty session. Guessing would report zero claims with
    // total confidence, which is the worst answer available.
    return { degraded: [detection.reason], provenance };
  }

  const acc = READERS[detection.format](parsed.records);
  const degraded: string[] = [];

  for (const failure of parsed.failures) {
    degraded.push(
      `transcript line ${failure.line} could not be parsed (${failure.error}); ` +
        "any file change it reported was NOT counted",
    );
  }

  if (acc.unknown.size > 0) {
    const names = [...acc.unknown.values()]
      .map((u) => `${u.name} x${u.count} (first at line ${u.first_line})`)
      .join(", ");
    degraded.push(
      `transcript contained ${acc.unknown.size} unrecognised event kind(s): ${names}. ` +
        "They were not read, so any file change they carried was not counted",
    );
  }

  if (!acc.lifecycle.started) {
    degraded.push("transcript has no session-start event; it may begin mid-session");
  }
  if (!acc.lifecycle.ended) {
    degraded.push(
      "transcript has no session-end event; the session was interrupted or is still running, " +
        "so later file changes may be missing",
    );
  }

  // Complete means both: it ended cleanly AND every line was readable.
  const complete = acc.lifecycle.ended && parsed.failures.length === 0;

  const session: AgentSession = {
    format: detection.format,
    source,
    ...(acc.session_id ? { session_id: acc.session_id } : {}),
    ...(acc.agent ? { agent: acc.agent } : {}),
    ...(acc.repo ? { repo: acc.repo } : {}),
    claimed_changes: [...acc.claims.values()].sort((a, b) => a.path.localeCompare(b.path)),
    lifecycle: acc.lifecycle,
    checkpoints: acc.checkpoints,
    unknown_events: [...acc.unknown.values()],
    records_parsed: parsed.records.length,
    complete,
    degraded,
    provenance,
  };

  return { session, degraded, provenance };
}

/**
 * Read a transcript from disk.
 *
 * A missing or unreadable file degrades rather than throws: the caller may have
 * supplied a path that does not exist, and that must not take down a
 * verification which git evidence alone can still answer.
 */
export async function loadSession(filePath: string): Promise<SessionEvidence> {
  try {
    const text = await readFile(filePath, "utf8");
    return parseSession(text, filePath);
  } catch (err) {
    return {
      degraded: [
        `could not read agent session transcript ${filePath} ` +
          `(${err instanceof Error ? err.message : String(err)}); ` +
          "the verdict rests on git evidence alone",
      ],
      provenance: provenanceFor(filePath),
    };
  }
}

export { detectFormat } from "./detect.js";

/**
 * Claim-reconciliation tests -- the Noon Curveball half of the adjudicator.
 *
 * The last test in this file is the one that matters most. It is a property
 * test over a matrix of contracts, diffs and transcripts, asserting the safety
 * invariant the revised design rests on:
 *
 *     severity(verdict | git + session) >= severity(verdict | git)
 *
 * If that ever fails, an incomplete transcript can lower a verdict -- which is
 * the exact failure this feature was designed not to introduce.
 */
import { test } from "node:test";
import assert from "node:assert/strict";

import { adjudicate } from "./adjudicate.js";
import {
  DEFAULT_POLICY,
  type ActualChanges,
  type AgentSession,
  type ChangeContract,
  type ClaimedChange,
  type Provenance,
  type Verdict,
} from "../types.js";

const DET: Provenance = {
  source: "graph.impact",
  command: "entire graph impact --symbol applyCoupon --repo . --depth 2 --profile full --format json",
  confidence: "deterministic",
};

const IN_RADIUS = "src/checkout/apply_coupon.ts";
const OBLIGED = "src/checkout/cart_total.ts";
const OUTSIDE = "src/billing/invoice.ts";

function contract(overrides: Partial<ChangeContract> = {}): ChangeContract {
  return {
    id: "ct-claims",
    created_at: "2026-09-06T00:00:00.000Z",
    repo_root: "/repo",
    base_sha: "base123",
    target: { symbol: "applyCoupon", file: IN_RADIUS },
    allowed_files: [
      { path: IN_RADIUS, reason: "definition site", provenance: DET },
      { path: OBLIGED, reason: "direct caller", provenance: DET },
    ],
    must_update: [{ path: OBLIGED, symbol: "cartTotal", relation: "CALLS", provenance: DET }],
    drift_candidates: [],
    known_traps: [],
    degraded: [],
    policy: DEFAULT_POLICY,
    ...overrides,
  };
}

function claim(path: string, kind: ClaimedChange["kind"] = "modified"): ClaimedChange {
  return { path, kind, line: 7, events: 1 };
}

function session(claims: ClaimedChange[], overrides: Partial<AgentSession> = {}): AgentSession {
  return {
    format: "acme-events",
    source: "fixture.jsonl",
    session_id: "s-1",
    claimed_changes: claims,
    lifecycle: { started: true, ended: true, status: "completed" },
    checkpoints: [],
    unknown_events: [],
    records_parsed: claims.length + 2,
    complete: true,
    degraded: [],
    provenance: {
      source: "transcript",
      command: "read agent session transcript fixture.jsonl",
      confidence: "claimed",
    },
    ...overrides,
  };
}

function actual(changed: string[], overrides: Partial<ActualChanges> = {}): ActualChanges {
  return {
    changed_files: changed,
    semantic_changes: undefined,
    head_sha: "head456",
    degraded: [],
    provenance: [],
    ...overrides,
  };
}

const RANK: Record<Verdict["status"], number> = { PASS: 0, WARN: 1, FAIL: 2 };

// ---------------------------------------------------------------------------
// evidence_basis
// ---------------------------------------------------------------------------

test("with no session supplied the verdict is deterministic and the claim buckets are empty", () => {
  const v = adjudicate(contract(), actual([IN_RADIUS, OBLIGED]));

  assert.equal(v.evidence_basis, "deterministic");
  assert.deepEqual(v.out_of_bounds_by_claim, []);
  assert.deepEqual(v.unverified_claims, []);
  assert.deepEqual(v.unclaimed_changes, []);
  assert.equal(v.status, "PASS");
});

test("with both sources present the verdict is reconciled", () => {
  const v = adjudicate(
    contract(),
    actual([IN_RADIUS, OBLIGED], { session: session([claim(IN_RADIUS), claim(OBLIGED)]) }),
  );

  assert.equal(v.evidence_basis, "reconciled");
  assert.equal(v.status, "PASS");
});

test("when git evidence is unavailable the basis is claimed_only", () => {
  const v = adjudicate(
    contract({ must_update: [] }),
    actual([], { git_unavailable: true, session: session([claim(IN_RADIUS)]) }),
  );

  assert.equal(v.evidence_basis, "claimed_only");
});

test("a claimed_only verdict can never be PASS", () => {
  const v = adjudicate(
    contract({ must_update: [], allowed_files: [{ path: IN_RADIUS, reason: "target", provenance: DET }] }),
    actual([], { git_unavailable: true, session: session([claim(IN_RADIUS)]) }),
  );

  assert.notEqual(v.status, "PASS");
  assert.ok(
    v.degraded.some((d) => d.toLowerCase().includes("claimed")),
    `degraded should explain the claim-only basis, got ${JSON.stringify(v.degraded)}`,
  );
});

// ---------------------------------------------------------------------------
// The three new finding classes
// ---------------------------------------------------------------------------

test("a claimed edit git cannot confirm is reported as an unverified claim", () => {
  const v = adjudicate(
    contract({ must_update: [] }),
    actual([IN_RADIUS], { session: session([claim(IN_RADIUS), claim(OBLIGED)]) }),
  );

  assert.deepEqual(
    v.unverified_claims.map((c) => c.path),
    [OBLIGED],
  );
});

test("an unverified claim alone is a WARN, never a FAIL", () => {
  const v = adjudicate(
    contract({ must_update: [] }),
    actual([IN_RADIUS], { session: session([claim(IN_RADIUS), claim(OBLIGED)]) }),
  );

  assert.equal(v.status, "WARN");
});

test("a git change the transcript never mentions is reported as unclaimed", () => {
  const v = adjudicate(
    contract(),
    actual([IN_RADIUS, OBLIGED], { session: session([claim(IN_RADIUS)]) }),
  );

  assert.deepEqual(
    v.unclaimed_changes.map((c) => c.path),
    [OBLIGED],
  );
  assert.equal(v.status, "WARN", "an out-of-band edit warns, it does not fail");
});

test("the agent claiming an edit outside the contract radius is a FAIL", () => {
  const v = adjudicate(
    contract(),
    actual([IN_RADIUS, OBLIGED], { session: session([claim(IN_RADIUS), claim(OUTSIDE)]) }),
  );

  assert.deepEqual(
    v.out_of_bounds_by_claim.map((c) => c.path),
    [OUTSIDE],
  );
  assert.equal(v.status, "FAIL");
});

test("an out-of-bounds claim is not double-reported as an unverified claim", () => {
  const v = adjudicate(
    contract(),
    actual([IN_RADIUS, OBLIGED], { session: session([claim(OUTSIDE)]) }),
  );

  assert.equal(
    v.unverified_claims.some((c) => c.path === OUTSIDE),
    false,
    "the stronger out-of-bounds finding subsumes the weaker unverified one",
  );
});

// ---------------------------------------------------------------------------
// The additive-only rule
// ---------------------------------------------------------------------------

test("a claimed edit does NOT discharge a must_update obligation", () => {
  // git shows only the definition edited; the transcript *claims* the obliged
  // caller was updated too. If the claim were allowed to satisfy the
  // obligation, a lying or truncated transcript would turn this FAIL into a PASS.
  const v = adjudicate(
    contract(),
    actual([IN_RADIUS], { session: session([claim(IN_RADIUS), claim(OBLIGED)]) }),
  );

  assert.deepEqual(
    v.forgotten.map((f) => f.path),
    [OBLIGED],
    "the obligation is still outstanding: only git can discharge it",
  );
  assert.equal(v.status, "FAIL");
});

test("a truncated transcript cannot turn a FAIL into a PASS", () => {
  const base = adjudicate(contract(), actual([IN_RADIUS]));
  assert.equal(base.status, "FAIL", "baseline: the obliged caller was not edited");

  const truncated = session([], {
    complete: false,
    lifecycle: { started: true, ended: false },
    degraded: ["transcript line 5 could not be parsed"],
  });
  const withTruncated = adjudicate(contract(), actual([IN_RADIUS], { session: truncated }));

  assert.equal(withTruncated.status, "FAIL");
});

test("an incomplete session is disclosed in the verdict's degraded list", () => {
  const incomplete = session([claim(IN_RADIUS)], {
    complete: false,
    lifecycle: { started: true, ended: false },
    degraded: ["transcript has no session-end event"],
  });
  const v = adjudicate(contract({ must_update: [] }), actual([IN_RADIUS], { session: incomplete }));

  assert.ok(
    v.degraded.some((d) => d.includes("session-end")),
    `the transcript's own degradation must reach the verdict, got ${JSON.stringify(v.degraded)}`,
  );
  assert.notEqual(v.status, "PASS", "an incomplete transcript cannot yield a clean PASS");
});

// ---------------------------------------------------------------------------
// THE SAFETY INVARIANT
// ---------------------------------------------------------------------------

test("property: adding session evidence never lowers the verdict severity", () => {
  const contracts = [
    contract(),
    contract({ must_update: [] }),
    contract({
      drift_candidates: [
        { path: "src/promotions/coupon.ts", detail: "co-changed in 3 commits", provenance: DET },
      ],
    }),
  ];

  const diffs = [[], [IN_RADIUS], [IN_RADIUS, OBLIGED], [IN_RADIUS, OBLIGED, OUTSIDE]];

  const sessions: AgentSession[] = [
    session([]),
    session([claim(IN_RADIUS)]),
    session([claim(IN_RADIUS), claim(OBLIGED)]),
    session([claim(OUTSIDE)]),
    session([claim(IN_RADIUS), claim(OBLIGED), claim(OUTSIDE)]),
    session([claim(IN_RADIUS)], {
      complete: false,
      lifecycle: { started: true, ended: false },
      degraded: ["truncated"],
    }),
    session([], {
      complete: false,
      unknown_events: [{ name: "thinking_block", count: 3, first_line: 2 }],
      degraded: ["unrecognised event kinds"],
    }),
  ];

  let checked = 0;
  for (const c of contracts) {
    for (const d of diffs) {
      const baseline = adjudicate(c, actual(d));
      for (const s of sessions) {
        const withSession = adjudicate(c, actual(d, { session: s }));
        assert.ok(
          RANK[withSession.status] >= RANK[baseline.status],
          `session evidence lowered the verdict from ${baseline.status} to ${withSession.status} ` +
            `for diff [${d.join(", ")}] and claims [${s.claimed_changes
              .map((x) => x.path)
              .join(", ")}]`,
        );
        checked += 1;
      }
    }
  }

  assert.equal(checked, contracts.length * diffs.length * sessions.length);
  assert.equal(checked, 84, "the matrix actually ran");
});

