/**
 * Traps recalled from a transcript's own checkpoint events.
 *
 * This is the "existing Checkpoint behaviour must remain compatible" half of
 * the Track 3 card. The CLI-sourced trap path (`entire checkpoint explain`) is
 * untouched; this adds a *second source* that produces the very same KnownTrap
 * type, so nothing downstream can tell them apart except by provenance.
 *
 * Note the confidence asymmetry, which is the interesting part: the CLI path
 * has to keyword-match unresolved work out of prose, whereas the new format
 * carries `open_questions[]` as a first-class field. Structured beats scraped.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { parseSession } from "./index.js";
import { trapsFromSession } from "./traps.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const fixtures = path.resolve(here, "..", "..", "..", "test", "fixtures");

function sessionFrom(name: string) {
  const text = readFileSync(path.join(fixtures, name), "utf8");
  const out = parseSession(text, name);
  assert.ok(out.session, `${name} should parse`);
  return out.session;
}

test("an open question in a transcript checkpoint becomes a known trap", () => {
  const out = trapsFromSession(sessionFrom("track-3-agent-session.jsonl"));

  assert.equal(out.traps.length, 1);
  assert.equal(
    out.traps[0]!.text,
    "Should expiry or disabled state take precedence in user-facing errors?",
  );
  assert.equal(out.traps[0]!.checkpoint_id, "cp-001");
});

test("a transcript trap carries the files the session claimed, so it can be hit later", () => {
  const out = trapsFromSession(sessionFrom("track-3-agent-session.jsonl"));

  assert.deepEqual(out.traps[0]!.files.sort(), [
    "src/checkout/apply_coupon.ts",
    "tests/checkout/apply_coupon.test.ts",
  ]);
});

test("a transcript trap is provenanced to the transcript, not to a checkpoint command", () => {
  const out = trapsFromSession(sessionFrom("track-3-agent-session.jsonl"));

  assert.equal(out.traps[0]!.provenance.source, "transcript");
  assert.equal(
    out.traps[0]!.provenance.confidence,
    "claimed",
    "the agent authored this question about its own work",
  );
});

test("a transcript with no checkpoint events yields no traps and says so", () => {
  const out = trapsFromSession(sessionFrom("session-entire-protocol.jsonl"));

  assert.deepEqual(out.traps, []);
  assert.ok(
    out.degraded.some((d) => d.includes("no checkpoint")),
    `expected a disclosure, got ${JSON.stringify(out.degraded)}`,
  );
});

test("an incomplete transcript discloses that later open questions may be missing", () => {
  const out = trapsFromSession(sessionFrom("session-incomplete.jsonl"));

  assert.deepEqual(out.traps, []);
  assert.ok(
    out.degraded.some((d) => d.toLowerCase().includes("incomplete")),
    `expected the incompleteness to be disclosed, got ${JSON.stringify(out.degraded)}`,
  );
});

/**
 * Rendering tests for the Curveball's new verdict buckets.
 *
 * The interface has to distinguish complete from incomplete context, so the
 * evidence basis is rendered as a banner rather than buried in a field, and
 * every claim-derived row is labelled [CLAIMED] so nobody mistakes the agent's
 * self-report for an observation.
 */
import { test } from "node:test";
import assert from "node:assert/strict";

import { formatVerdict } from "./format.js";
import type { Provenance, Verdict } from "./types.js";

const CLAIM: Provenance = {
  source: "transcript",
  command: "read agent session transcript test/fixtures/track-3-agent-session.jsonl",
  confidence: "claimed",
};

function verdict(overrides: Partial<Verdict> = {}): Verdict {
  return {
    status: "PASS",
    evidence_basis: "deterministic",
    out_of_bounds: [],
    out_of_bounds_by_claim: [],
    unverified_claims: [],
    unclaimed_changes: [],
    forgotten: [],
    drift_candidates: [],
    traps_hit: [],
    in_bounds: [],
    semantic_changes: undefined,
    degraded: [],
    contract_id: "ct-fmt",
    base_sha: "abcdef1234",
    head_sha: "1234abcdef",
    ...overrides,
  };
}

test("the evidence basis is rendered so a reader sees what the verdict rests on", () => {
  const text = formatVerdict(verdict({ evidence_basis: "reconciled" }));

  assert.ok(text.includes("EVIDENCE BASIS"), text.slice(0, 300));
  assert.ok(text.includes("reconciled"), text.slice(0, 300));
});

test("a claimed_only verdict says in words that it cannot be authoritative", () => {
  const text = formatVerdict(verdict({ status: "WARN", evidence_basis: "claimed_only" }));

  assert.ok(
    text.toLowerCase().includes("cannot be a pass"),
    "the banner must state the constraint, not just the label",
  );
});

test("an out-of-bounds claim renders with its transcript evidence", () => {
  const text = formatVerdict(
    verdict({
      status: "FAIL",
      out_of_bounds_by_claim: [
        { path: "src/billing/invoice.ts", note: "outside the proved radius", provenance: CLAIM },
      ],
    }),
  );

  assert.ok(text.includes("OUT OF BOUNDS BY CLAIM (1)"), text);
  assert.ok(text.includes("src/billing/invoice.ts"), text);
  assert.ok(text.includes(CLAIM.command), "the provenance command must be printed");
});

test("claim-derived rows are labelled so a self-report is never read as an observation", () => {
  const text = formatVerdict(
    verdict({
      status: "WARN",
      unverified_claims: [{ path: "a.ts", note: "not in the diff", provenance: CLAIM }],
      unclaimed_changes: [{ path: "b.ts", note: "not in the transcript", provenance: CLAIM }],
    }),
  );

  assert.ok(text.includes("UNVERIFIED CLAIMS (1)"), text);
  assert.ok(text.includes("UNCLAIMED CHANGES (1)"), text);
  assert.ok(text.includes("CLAIMED"), "claim rows must carry a confidence label");
});

test("with no session the claim sections stay out of the way", () => {
  const text = formatVerdict(verdict());

  assert.equal(
    text.includes("OUT OF BOUNDS BY CLAIM"),
    false,
    "a git-only verdict should render exactly as it did before the Curveball",
  );
  assert.equal(text.includes("UNVERIFIED CLAIMS"), false);
});

/**
 * Traps recalled from a transcript's own checkpoint events.
 *
 * The Track 3 card requires existing Checkpoint behaviour to stay compatible.
 * It does: the `entire checkpoint explain` path in `evidence/checkpoints.ts` is
 * untouched. This is a *second source* feeding the same `KnownTrap` type, so
 * `propose_change`, the adjudicator and the formatter need no knowledge that a
 * trap can now come from a transcript.
 *
 * One asymmetry is worth naming, because it runs the opposite way to the rest
 * of this feature. The CLI path has to keyword-match unresolved work out of
 * checkpoint prose, and its recall is therefore limited. The new transcript
 * format carries `open_questions[]` as a first-class field: the agent declared
 * these as unresolved, so no scraping is involved. The provenance stays
 * "claimed" because the agent authored it about its own work -- but it is a
 * structured claim rather than a guess about prose.
 */
import type { AgentSession, KnownTrap } from "../../types.js";

export type SessionTrapEvidence = { traps: KnownTrap[]; degraded: string[] };

export function trapsFromSession(session: AgentSession): SessionTrapEvidence {
  const traps: KnownTrap[] = [];
  const degraded: string[] = [];

  // The files this session says it touched. A trap raised by the session is
  // relevant to the territory the session worked in, which is what lets
  // `traps_hit` fire later if that territory is edited again.
  const files = session.claimed_changes.map((c) => c.path);

  for (const checkpoint of session.checkpoints) {
    for (const question of checkpoint.open_questions) {
      traps.push({
        text: question,
        checkpoint_id: checkpoint.checkpoint_id,
        files,
        provenance: session.provenance,
      });
    }
  }

  if (session.checkpoints.length === 0) {
    degraded.push(
      `transcript ${session.source} records no checkpoint events, so no open questions were ` +
        "recalled from it; checkpoint history from the Entire CLI is unaffected",
    );
  } else if (traps.length === 0) {
    degraded.push(
      `transcript ${session.source} records ${session.checkpoints.length} checkpoint event(s) but ` +
        "none carried open questions",
    );
  }

  if (!session.complete) {
    degraded.push(
      `transcript ${session.source} is incomplete, so open questions raised after the point of ` +
        "truncation are missing from this contract",
    );
  }

  return { traps, degraded };
}

